#!/bin/bash -l

# --- 1. CONFIGURATION ---
# Set the path to your project root
PROJECT_ROOT=~/xai-concept-leakage

# Set the path to your main YAML config file
EXPERIMENT_CONFIG=$PROJECT_ROOT/experiments/configs/tabulartoy.yaml

# --- 2. COUNT TASKS ---
# This Python script reads your YAML and counts how many individual
# experiments are generated by expanding your 'runs' list.
NUM_TASKS=$(python - <<EOF
import yaml
import copy
import sys
# Add the project root to the path to find your utils
sys.path.insert(0, "$PROJECT_ROOT")
from experiments import experiment_utils

try:
    with open("$EXPERIMENT_CONFIG", "r") as f:
        config = yaml.load(f, Loader=yaml.FullLoader)
except FileNotFoundError:
    print(f"Error: Config file not found at {EXPERIMENT_CONFIG}", file=sys.stderr)
    sys.exit(1)
except ImportError as e:
    print(f"Error: Could not import experiment_utils. Make sure PROJECT_ROOT is correct.", file=sys.stderr)
    print(e, file=sys.stderr)
    sys.exit(1)

shared_params = config.get("shared_params", {})
all_runs = []
if "runs" not in config:
    print(f"Error: 'runs' key not found in {EXPERIMENT_CONFIG}", file=sys.stderr)
    sys.exit(1)

for current_config in config["runs"]:
    trial_config = copy.deepcopy(shared_params)
    trial_config.update(current_config)
    # This function correctly expands any hyperparameter lists
    for run_config in experiment_utils.generate_hyperparamter_configs(trial_config):
        all_runs.append(run_config)
print(len(all_runs))
EOF
)

if [ $? -ne 0 ] || [ -z "$NUM_TASKS" ] || [ "$NUM_TASKS" -eq 0 ]; then
    echo "Error: Failed to count tasks. Check your Python script and YAML file."
    exit 1
fi

echo "Found $NUM_TASKS total experiments in $EXPERIMENT_CONFIG"
echo "Submitting SGE job array..."

# --- 3. SUBMIT THE ARRAY JOB ---
# This passes the config path as an argument to the worker script
qsub -t 1-$NUM_TASKS $PROJECT_ROOT/experiments/run_worker.sh $EXPERIMENT_CONFIG

echo "Job array submitted."